struct Info { int RefCount; int Deleted; };
struct Counted {
    void* Data; Info* I;
    Counted() : Data(0), I(0) { }
    Counted(void* d, Info* i) : Data(d), I(i) { if (I) ++I->RefCount; }
    Counted(const Counted& o) : Data(o.Data), I(o.I) { if (I) ++I->RefCount; }
