static bool Less(const Entry& a, const Entry& b) { return a.first < b.first; }
static void LinearInsert(Entry* first, Entry* last, Entry val)
{
    if (Less(val, *first)) {
        for (Entry* p = last; p != first; --p) p[0] = p[-1];
        *first = val;
    } else {
        Entry* next = last - 1;
